  )
}

import Image from '@tiptap/extension-image'
import {
  mergeAttributes,
  NodeViewWrapper,
  type ReactNodeViewProps,
  ReactNodeViewRenderer,
  useCurrentEditor
} from '@tiptap/react'
import { AlignLeftIcon, ChevronDownIcon, TrashIcon } from 'lucide-react'
import { type CSSProperties, type ImgHTMLAttributes, type PointerEvent, useRef, useState } from 'react'
import { Button } from '@/components/atoms/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from '@/components/atoms/dropdown-menu'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/atoms/popover'
import { Separator } from '@/components/atoms/separator'
import { Skeleton } from '@/components/atoms/skeleton'
import { cn } from '@/utils/ui'
import { type Alignment, alignments, containerClassNamePerAlignment, minWidth } from './lib'

type ImageAttributes = Pick<ImgHTMLAttributes<HTMLImageElement>, 'alt' | 'height' | 'src' | 'title' | 'width'> & {
  alignment: Alignment
  containerStyle: CSSProperties
}

type ResizingPosition = 'left' | 'right'

const BASE_RESIZE_HANDLER_CLASS_NAME =
  'invisible absolute top-0 bottom-0 cursor-ew-resize px-2 transition-[visibility_width] group-hover:visible before:absolute before:top-1/2 before:h-1/2 before:max-h-36 before:w-1 before:-translate-y-1/2 before:rounded-md before:bg-muted before:border-muted-foreground before:content-[""]'

function ImageComponent({ node, updateAttributes, deleteNode }: ReactNodeViewProps<HTMLImageElement>) {
  const { alignment, containerStyle, ...imageAttributes } = node.attrs as ImageAttributes

  const { editor } = useCurrentEditor()

  const containerRef = useRef<HTMLDivElement>(null)
  const [isLoaded, setIsLoaded] = useState(false)
  const [isOpenPopover, setIsOpenPopover] = useState(false)

  function loadImage() {
    setIsLoaded(true)
  }

  function changeAlignment(alignment: Alignment) {
    // Update alignment
    updateAttributes({
      alignment
    })

    // Update width (full) if alignment is justify
    if (alignment === 'justify') {
      updateAttributes({
        containerStyle: {
          ...containerStyle,
          width: '100%'
        },
        width: containerRef.current?.clientWidth
      })
    }

    // Focus editor
    editor?.commands.focus()
  }

  function downPointer(pointerDownEvent: PointerEvent<HTMLDivElement>, position: ResizingPosition) {
    pointerDownEvent.preventDefault()
    pointerDownEvent.stopPropagation()

    // Handle move pointer
    function handleMovePointer(pointerMoveEvent: MouseEvent) {
      pointerMoveEvent.preventDefault()
      pointerMoveEvent.stopPropagation()

      const containerWidth = containerRef.current?.clientWidth ?? 0
      const deltaX =
        (position === 'left'
          ? pointerDownEvent.clientX - pointerMoveEvent.clientX
          : pointerMoveEvent.clientX - pointerDownEvent.clientX) * 2
      const newWidth = Math.round(
        Math.max(minWidth, Math.min(containerWidth, (imageAttributes.width as number) + deltaX))
      )

      updateAttributes({
        containerStyle: {
          ...containerStyle,
          width: `${Math.round((newWidth * 100) / containerWidth)}%`
        },
        width: newWidth
      })
    }

    // Handle up pointer
    const handleUpPointer = (pointerUpEvent: MouseEvent) => {
      pointerUpEvent.preventDefault()
      pointerUpEvent.stopPropagation()

      editor?.commands.focus()

      document.removeEventListener('pointermove', handleMovePointer)
      document.removeEventListener('pointerup', handleUpPointer)
    }

    document.addEventListener('pointermove', handleMovePointer)
    document.addEventListener('pointerup', handleUpPointer)
  }

  function deleteImage() {
    deleteNode()
    editor?.commands.focus()
  }

  return (
    <NodeViewWrapper data-drag-handle>
      <div className={cn('flex', containerClassNamePerAlignment[alignment])} ref={containerRef}>
        <div className='group relative transition-all' style={containerStyle}>
          {!isLoaded && <Skeleton className='absolute inset-0 rounded-md' />}

          <Popover onOpenChange={setIsOpenPopover} open={isOpenPopover}>
            <PopoverTrigger className='w-full'>
              {/** biome-ignore lint/correctness/useImageSize:ignore */}
              {/** biome-ignore lint/a11y/noNoninteractiveElementInteractions: ignore */}
              <img
                {...imageAttributes}
                alt='Alt'
                className={cn(
                  'peer pointer-events-none w-full object-contain opacity-0 outline-2 outline-transparent outline-offset-2 transition-all',
                  {
                    'outline-inherit': isOpenPopover,
                    'pointer-events-auto opacity-100': isLoaded
                  }
                )}
                onLoad={loadImage}
              />
            </PopoverTrigger>

            <PopoverContent className='space-y-4' side='top'>
              <div className='flex gap-2'>
                {/* Alignment */}
                <DropdownMenu>
                  <DropdownMenuTrigger
                    render={
                      <Button variant='outline'>
                        <AlignLeftIcon />
                        <ChevronDownIcon />
                      </Button>
                    }
                  />

                  <DropdownMenuContent>
                    {alignments.map((alignmentOption) => (
                      <DropdownMenuItem
                        className={cn({
                          'bg-accent': alignment === alignmentOption.value
                        })}
                        key={alignmentOption.value}
                        onClick={() => changeAlignment(alignmentOption.value)}
                      >
                        <alignmentOption.icon />
                        <span>{alignmentOption.label}</span>
                      </DropdownMenuItem>
                    ))}
                  </DropdownMenuContent>
                </DropdownMenu>

                <Separator className='h-10' orientation='vertical' />

                {/* Trash */}
                <Button onClick={deleteImage} size='icon' variant='outline'>
                  <TrashIcon />
                </Button>
              </div>
            </PopoverContent>
          </Popover>

          <div
            className={cn('left-1 before:left-1.5', BASE_RESIZE_HANDLER_CLASS_NAME)}
            onPointerDown={(e) => downPointer(e, 'left')}
          />

          <div
            className={cn('right-1 before:right-1.5', BASE_RESIZE_HANDLER_CLASS_NAME)}
            onPointerDown={(e) => downPointer(e, 'right')}
          />
        </div>
      </div>
    </NodeViewWrapper>
  )
}

const CustomImageExtension = Image.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      alignment: {
        default: 'center'
      },
      containerStyle: {
        default: {
          width: `${minWidth}px`
        }
      },
      width: {
        default: minWidth
      }
    }
  },
  addNodeView() {
    return ReactNodeViewRenderer(ImageComponent)
  },
  renderHTML({ HTMLAttributes }) {
    const { alignment, containerStyle, ...imageAttributes } = HTMLAttributes as ImageAttributes
    return [
      'div',
      {
        class: cn('flex', containerClassNamePerAlignment[alignment])
      },
      [
        'div',
        {
          style: Object.entries(containerStyle)
            .map(([key, value]) => `${key}: ${value}`)
            .join(';')
        },
        [
          'img',
          {
            ...mergeAttributes(imageAttributes),
            class: 'w-full object-contain rounded-md'
          }
        ]
      ]
    ]
  }
})

export default CustomImageExtension

import Youtube from '@tiptap/extension-youtube'
import {
  mergeAttributes,
  NodeViewWrapper,
  type ReactNodeViewProps,
  ReactNodeViewRenderer,
  useCurrentEditor
} from '@tiptap/react'
import { AlignLeftIcon, ChevronDownIcon, MoveHorizontalIcon, TrashIcon } from 'lucide-react'
import { type CSSProperties, type IframeHTMLAttributes, useRef, useState } from 'react'
import { Button } from '@/components/atoms/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from '@/components/atoms/dropdown-menu'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/atoms/popover'
import { Separator } from '@/components/atoms/separator'
import { Skeleton } from '@/components/atoms/skeleton'
import { cn } from '@/utils/ui'
import { type Alignment, alignments, containerClassNamePerAlignment, isValidYoutubeUrl, minWidth } from './lib'

type YoutubeAttributes = IframeHTMLAttributes<HTMLIFrameElement> & {
  alignment: Alignment
  containerStyle: CSSProperties
}

const widthSizes: string[] = ['25%', '50%', '75%', '100%']

function getYoutubeEmbedUrl(nocookie?: boolean, isPlaylist?: boolean) {
  if (isPlaylist) {
    return 'https://www.youtube-nocookie.com/embed/videoseries?list='
  }
  return nocookie ? 'https://www.youtube-nocookie.com/embed/' : 'https://www.youtube.com/embed/'
}

function getEmbedUrlFromYoutubeUrl(options: {
  url: string
  allowFullscreen?: boolean
  autoplay?: boolean
  ccLanguage?: string
  ccLoadPolicy?: boolean
  controls?: boolean
  disableKBcontrols?: boolean
  enableIFrameApi?: boolean
  endTime?: number
  interfaceLanguage?: string
  ivLoadPolicy?: number
  loop?: boolean
  modestBranding?: boolean
  nocookie?: boolean
  origin?: string
  playlist?: string
  progressBarColor?: string
  startAt?: number
  rel?: number
}) {
  const {
    url,
    allowFullscreen,
    autoplay,
    ccLanguage,
    ccLoadPolicy,
    controls,
    disableKBcontrols,
    enableIFrameApi,
    endTime,
    interfaceLanguage,
    ivLoadPolicy,
    loop,
    modestBranding,
    nocookie,
    origin,
    playlist,
    progressBarColor,
    startAt,
    rel
  } = options

  if (!isValidYoutubeUrl(url)) {
    return null
  }

  // If is already an embed url, return it
  if (url.includes('/embed/')) {
    return url
  }

  // If is a youtu.be url, get the id after the /
  if (url.includes('youtu.be')) {
    const id = url.split('/').pop()

    if (!id) {
      return null
    }
    return `${getYoutubeEmbedUrl(nocookie)}${id}`
  }

  const videoIdRegex = /(?:(v|list)=|shorts\/)([-\w]+)/gm
  const matches = videoIdRegex.exec(url)

  if (!matches?.[2]) {
    return null
  }

  let outputUrl = `${getYoutubeEmbedUrl(nocookie, matches[1] === 'list')}${matches[2]}`

  const params: string[] = []

  if (allowFullscreen === false) {
    params.push('fs=0')
  }

  if (autoplay) {
    params.push('autoplay=1')
  }

  if (ccLanguage) {
    params.push(`cc_lang_pref=${ccLanguage}`)
  }

  if (ccLoadPolicy) {
    params.push('cc_load_policy=1')
  }

  if (!controls) {
    params.push('controls=0')
  }

  if (disableKBcontrols) {
    params.push('disablekb=1')
  }

  if (enableIFrameApi) {
    params.push('enablejsapi=1')
  }

  if (endTime) {
    params.push(`end=${endTime}`)
  }

  if (interfaceLanguage) {
    params.push(`hl=${interfaceLanguage}`)
  }

  if (ivLoadPolicy) {
    params.push(`iv_load_policy=${ivLoadPolicy}`)
  }

  if (loop) {
    params.push('loop=1')
  }

  if (modestBranding) {
    params.push('modestbranding=1')
  }

  if (origin) {
    params.push(`origin=${origin}`)
  }

  if (playlist) {
    params.push(`playlist=${playlist}`)
  }

  if (startAt) {
    params.push(`start=${startAt}`)
  }

  if (progressBarColor) {
    params.push(`color=${progressBarColor}`)
  }

  if (rel !== undefined) {
    params.push(`rel=${rel}`)
  }

  if (params.length) {
    outputUrl += `${matches[1] === 'v' ? '?' : '&'}${params.join('&')}`
  }

  return outputUrl
}

function YoutubeComponent(props: ReactNodeViewProps<HTMLImageElement>) {
  const { node, updateAttributes, deleteNode } = props
  const { alignment, containerStyle, ...youtubeAttributes } = node.attrs as YoutubeAttributes

  const { editor } = useCurrentEditor()

  const containerRef = useRef<HTMLDivElement>(null)
  const [src] = useState(
    () =>
      getEmbedUrlFromYoutubeUrl({
        nocookie: true,
        url: youtubeAttributes.src as string
      }) ?? undefined
  )
  const [loaded, setLoaded] = useState(false)
  const [openPopover, setOpenPopover] = useState(false)

  function loadVideo() {
    setLoaded(true)
  }

  function changeAlignment(alignment: Alignment) {
    updateAttributes({
      alignment
    })

    if (alignment === 'justify') {
      updateAttributes({
        containerStyle: {
          ...containerStyle,
          width: '100%'
        },
        width: containerRef.current?.clientWidth
      })
    }

    // Focus editor
    editor?.commands.focus()
  }

  function changeWidthSize(size: string) {
    updateAttributes({
      containerStyle: {
        ...containerStyle,
        width: size
      }
    })
    editor?.commands.focus()
  }

  function deleteVideo() {
    deleteNode()
    editor?.commands.focus()
  }

  return (
    <NodeViewWrapper data-drag-handle>
      <div className={cn('flex', containerClassNamePerAlignment[alignment])} ref={containerRef}>
        <Popover onOpenChange={setOpenPopover} open={openPopover}>
          <PopoverTrigger
            className={cn('group relative aspect-video rounded-md border p-6 transition-all', {
              'border-primary': openPopover,
              'pointer-events-auto opacity-100': loaded
            })}
            style={containerStyle}
          >
            {!loaded && <Skeleton className='pointer-events-none absolute inset-0 rounded-md' />}

            {/** biome-ignore lint/a11y/noNoninteractiveElementInteractions: ignore */}
            <iframe
              allowFullScreen={false}
              className='size-full rounded-md object-contain'
              height={youtubeAttributes.height}
              onLoad={loadVideo}
              src={src}
              title='custom-youtube-extension'
              width={youtubeAttributes.width}
            />
          </PopoverTrigger>

          <PopoverContent className='space-y-4' side='top'>
            <div className='flex gap-2'>
              {/* Alignment */}
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <Button variant='outline'>
                      <AlignLeftIcon />
                      <ChevronDownIcon />
                    </Button>
                  }
                />

                <DropdownMenuContent>
                  {alignments.map((alignmentOption) => (
                    <DropdownMenuItem
                      className={cn({
                        'bg-accent': alignment === alignmentOption.value
                      })}
                      key={alignmentOption.value}
                      onClick={() => changeAlignment(alignmentOption.value)}
                    >
                      <alignmentOption.icon />
                      <span>{alignmentOption.label}</span>
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>

              <Separator className='h-10' orientation='vertical' />

              {/* Width size */}
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <Button variant='outline'>
                      <MoveHorizontalIcon />
                      <ChevronDownIcon />
                    </Button>
                  }
                />

                <DropdownMenuContent>
                  {widthSizes.map((size) => (
                    <DropdownMenuItem
                      className={cn({
                        'bg-accent': containerStyle.width === size
                      })}
                      key={size}
                      onClick={() => changeWidthSize(size)}
                    >
                      {size}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>

              <Separator className='h-10' orientation='vertical' />

              {/* Trash */}
              <Button onClick={deleteVideo} size='icon' variant='outline'>
                <TrashIcon />
              </Button>
            </div>
          </PopoverContent>
        </Popover>
      </div>
    </NodeViewWrapper>
  )
}

const CustomYoutubeExtension = Youtube.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      alignment: {
        default: 'center'
      },
      containerStyle: {
        default: {
          width: `${minWidth}px`
        }
      }
    }
  },
  addNodeView() {
    return ReactNodeViewRenderer(YoutubeComponent)
  },
  renderHTML({ HTMLAttributes }) {
    const { alignment, containerStyle, ...youtubeAttributes } = HTMLAttributes as YoutubeAttributes

    const embedUrl = getEmbedUrlFromYoutubeUrl({
      allowFullscreen: this.options.allowFullscreen,
      autoplay: this.options.autoplay,
      ccLanguage: this.options.ccLanguage,
      ccLoadPolicy: this.options.ccLoadPolicy,
      controls: this.options.controls,
      disableKBcontrols: this.options.disableKBcontrols,
      enableIFrameApi: this.options.enableIFrameApi,
      endTime: this.options.endTime,
      interfaceLanguage: this.options.interfaceLanguage,
      ivLoadPolicy: this.options.ivLoadPolicy,
      loop: this.options.loop,
      modestBranding: this.options.modestBranding,
      nocookie: this.options.nocookie,
      origin: this.options.origin,
      playlist: this.options.playlist,
      progressBarColor: this.options.progressBarColor,
      rel: this.options.rel,
      startAt: HTMLAttributes.start || 0,
      url: HTMLAttributes.src
    })

    if (embedUrl) {
      youtubeAttributes.src = embedUrl
    }

    return [
      'div',
      {
        class: cn('flex', containerClassNamePerAlignment[alignment])
      },
      [
        'div',
        {
          class: 'aspect-video',
          style: Object.entries(containerStyle)
            .map(([key, value]) => `${key}: ${value}`)
            .join(';')
        },
        [
          'iframe',
          {
            ...mergeAttributes(
              this.options.HTMLAttributes,
              {
                allowfullscreen: this.options.allowFullscreen,
                autoplay: this.options.autoplay,
                ccLanguage: this.options.ccLanguage,
                ccLoadPolicy: this.options.ccLoadPolicy,
                disableKBcontrols: this.options.disableKBcontrols,
                enableIFrameApi: this.options.enableIFrameApi,
                endTime: this.options.endTime,
                height: this.options.height,
                interfaceLanguage: this.options.interfaceLanguage,
                ivLoadPolicy: this.options.ivLoadPolicy,
                loop: this.options.loop,
                modestBranding: this.options.modestBranding,
                origin: this.options.origin,
                playlist: this.options.playlist,
                progressBarColor: this.options.progressBarColor,
                rel: this.options.rel,
                width: this.options.width
              },
              youtubeAttributes
            ),
            class: 'size-full rounded-md object-contain'
          }
        ]
      ]
    ]
  }
})

export default CustomYoutubeExtension

import type { Content } from '@tiptap/react'
import parse from 'html-react-parser'

export function EditorContent({ content }: { content: Content }) {
  if (typeof content === 'string') {
    return <div className='tiptap'>{parse(content)}</div>
  }
  return null
}

import { useForm } from '@tanstack/react-form'
import { useEditorState } from '@tiptap/react'
import { CheckCircleIcon, PaperclipIcon } from 'lucide-react'
import { useState } from 'react'
import type { DropzoneOptions } from 'react-dropzone'
import { toast } from 'sonner'
import z from 'zod'
import { Button } from '@/components/atoms/button'
import { Field, FieldError, FieldLabel } from '@/components/atoms/field'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/atoms/popover'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/atoms/tooltip'
import {
  FileUpload,
  FileUploadContent,
  FileUploadInput,
  FileUploadItem,
  type FileUploadProps
} from '@/components/molecules/file-upload/file-upload'
import { getFileUrl, type UploadedFile, useFileUpload } from '@/components/molecules/file-upload/lib'
import { useInternalEditor } from './lib'

export const fileFormSchema = z.object({
  files: z.array(z.custom<File>()).min(1, 'Please select the file')
})

export const defaultFileFormValue: z.input<typeof fileFormSchema> = {
  files: []
}

export const fileUploaderDropzoneOptions: DropzoneOptions = {
  accept: {
    'application/msword': ['.doc'],
    'application/pdf': ['.pdf'],
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'],
    'application/xml': ['.xml']
  },
  maxFiles: 10,
  multiple: true
}

export default function FileButton({ id }: { id: string }) {
  const editor = useInternalEditor()
  const editorState = useEditorState({
    editor,
    selector: ({ editor }) => ({
      isEditable: editor.isEditable
    })
  })

  const [openPopover, setOpenPopover] = useState(false)
  const { fileUploadPending, uploadFile } = useFileUpload()

  const fileForm = useForm({
    defaultValues: defaultFileFormValue,
    formId: `${id}-file-form`,
    onSubmit: async ({ value }) => {
      try {
        const { files } = fileFormSchema.parse(value)

        // Upload file
        const uploadedFiles = (await Promise.all(files.map(async (file) => await uploadFile(file)))).filter(
          Boolean
        ) as UploadedFile[]

        // Add file node view
        for (const uploadedFile of uploadedFiles) {
          editor
            ?.chain()
            .focus()
            // @ts-expect-error - custom command from FileExtension
            .insertFile({
              mime: uploadedFile.mime,
              name: uploadedFile.original,
              size: uploadedFile.compress_info[''].size,
              url: getFileUrl(uploadedFile.path)
            })
            .run()
        }

        // Enter new line
        if (uploadedFiles.length > 0) {
          editor?.commands.enter()
        }

        // Close popover
        setOpenPopover(false)
      } catch {
        toast.error('Failure', {
          description: 'An error occurred, please try again'
        })
      }
    },
    validators: {
      onSubmit: fileFormSchema
    }
  })

  return (
    <Popover
      onOpenChange={(open) => {
        setOpenPopover(open)
        if (!open) {
          fileForm.reset()
        }
      }}
      open={openPopover}
    >
      <Tooltip>
        <TooltipTrigger
          render={
            <PopoverTrigger
              render={
                <Button disabled={!editorState.isEditable} size='icon' variant='ghost'>
                  <PaperclipIcon />
                </Button>
              }
            />
          }
        />

        <TooltipContent>File</TooltipContent>
      </Tooltip>

      <PopoverContent className='w-xs'>
        <div>Acceptable formats: doc, docx, xlsx, xml, pdf</div>

        <form
          className='space-y-4'
          id={fileForm.formId}
          onSubmit={(e) => {
            e.preventDefault()
            fileForm.handleSubmit()
          }}
        >
          <fileForm.Field name='files'>
            {(field) => {
              const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
              return (
                <Field data-invalid={isInvalid}>
                  <FieldLabel htmlFor={`editor-${fileForm.formId}-files`}>Files *</FieldLabel>

                  <FileUpload
                    className='xl:grid-cols-1'
                    {...fileUploaderDropzoneOptions}
                    onValueChange={field.handleChange as FileUploadProps['onValueChange']}
                    value={field.state.value}
                  >
                    <FileUploadInput aria-invalid={isInvalid} id={`editor-${fileForm.formId}-files`} />
                    <FileUploadContent>
                      {field.state.value.map((value, index) => (
                        <FileUploadItem
                          index={index}
                          // biome-ignore lint/suspicious/noArrayIndexKey: ignore
                          key={index}
                          value={value}
                        />
                      ))}
                    </FileUploadContent>
                  </FileUpload>

                  {isInvalid && <FieldError errors={field.state.meta.errors} />}
                </Field>
              )
            }}
          </fileForm.Field>

          <div className='flex items-center justify-end gap-2'>
            <fileForm.Subscribe selector={(state) => [state.canSubmit, state.isSubmitting]}>
              {([canSubmit, isSubmitting]) => (
                <Tooltip>
                  <TooltipTrigger
                    render={
                      <Button
                        disabled={!canSubmit}
                        form={fileForm.formId}
                        loading={fileUploadPending || isSubmitting}
                        size='icon'
                        type='submit'
                        variant='outline'
                      >
                        <CheckCircleIcon />
                      </Button>
                    }
                  />
                  <TooltipContent>submitButton</TooltipContent>
                </Tooltip>
              )}
            </fileForm.Subscribe>
          </div>
