      </Tooltip>

      <DropdownMenuContent>
        <DropdownMenuGroup>
          {textStyles.map((textStyle) => {
            const isActive = editorState?.isActive[`${textStyle.level}`]
            return (
              <DropdownMenuItem
                className={cn({
                  'bg-accent text-accent-foreground': isActive
                })}
                key={textStyle.level}
