import { Input } from '@/components/atoms/input'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/atoms/popover'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/atoms/tooltip'
import type { CallbackRef, SetExtensions } from './editor'
import { isValidYoutubeUrl, minWidth, useInternalEditor } from './lib'

const youtubeFormSchema = z.object({
  url: z
    .string()
    .trim()
    .min(1, 'Please enter the URL')
    .refine((value) => isValidYoutubeUrl(value), 'URL is invalid')
})

const defaultYoutubeFormValue: z.input<typeof youtubeFormSchema> = {
  url: ''
}

export default function YoutubeButton({
  id,
  callbackRef,
  setExtensions
}: {
  id: string
  callbackRef: CallbackRef
  setExtensions: SetExtensions
}) {
  const editor = useInternalEditor()
  const editorState = useEditorState({
    editor,
    selector: ({ editor }) => ({
      isEditable: editor.isEditable
    })
  })

  const isExtensionLoadedRef = useRef(false)
  const [openPopover, setOpenPopover] = useState(false)
  const [isPending, startTransition] = useTransition()

  const youtubeForm = useForm({
    defaultValues: defaultYoutubeFormValue,
    formId: `${id}-youtube-form`,
    onSubmit: ({ value }) => {
      const { url } = youtubeFormSchema.parse(value)
      const callback: CallbackRef['current'] = (editor) => {
        editor
          ?.chain()
          .focus()
          .setYoutubeVideo({
            src: url
          })
          .enter()
          .run()
      }

      // Add youtube node view
      if (isExtensionLoadedRef.current) {
        return callback(editor)
      }

      // Load extension
      startTransition(async () => {
        try {
          const { default: CustomYoutubeExtension } = await import('./custom-youtube-extension')

          callbackRef.current = callback

          setExtensions((prev) => [
            ...prev,
            CustomYoutubeExtension.configure({
              height: 180,
              nocookie: true,
              width: minWidth
            })
          ])

          isExtensionLoadedRef.current = true
        } catch (error) {
          console.error('An error occurred when load the CustomYoutube extension', error)
        }
      })

      // Close popover
      setOpenPopover(false)
    },
    validators: {
      onSubmit: youtubeFormSchema
    }
  })

  return (
    <Popover
      onOpenChange={(open) => {
        setOpenPopover(open)
        if (!open) {
          youtubeForm.reset()
        }
      }}
      open={openPopover}
    >
      <Tooltip>
        <TooltipTrigger
          render={
            <PopoverTrigger
              render={
                <Button disabled={!editorState.isEditable} loading={isPending} size='icon' variant='ghost'>
                  <TvMinimalPlay />
                </Button>
              }
            />
          }
        />
        <TooltipContent>YouTube</TooltipContent>
      </Tooltip>

      <PopoverContent className='w-xs'>
        <form
          className='space-y-4'
          id={youtubeForm.formId}
          onSubmit={(e) => {
            e.preventDefault()
            e.stopPropagation()
            youtubeForm.handleSubmit()
          }}
        >
          <youtubeForm.Field name='url'>
            {(field) => {
              const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
              return (
                <Field data-invalid={isInvalid}>
                  <FieldLabel htmlFor={`editor-${id}-url`}>
                    <span>URL</span> <span className='text-destructive'>*</span>
                  </FieldLabel>

                  <Input
                    aria-invalid={isInvalid}
                    id={`editor-${id}-url`}
                    name={field.name}
                    onBlur={field.handleBlur}
                    onChange={(e) => field.handleChange(e.target.value)}
                    placeholder={'Enter URL'}
                    value={field.state.value}
                  />

                  {isInvalid && <FieldError errors={field.state.meta.errors} />}
                </Field>
              )
            }}
          </youtubeForm.Field>

          <div className='flex items-center justify-end gap-1'>
            <youtubeForm.Subscribe selector={(state) => [state.canSubmit, state.isSubmitting]}>
              {([canSubmit, isSubmitting]) => (
                <Tooltip>
                  <TooltipTrigger
                    render={
                      <Button
                        disabled={!canSubmit}
                        form={youtubeForm.formId}
                        loading={isSubmitting}
                        size='icon'
                        type='submit'
                        variant='outline'
                      >
                        <CheckCircle />
                      </Button>
                    }
                  />
                  <TooltipContent>Save</TooltipContent>
                </Tooltip>
              )}
            </youtubeForm.Subscribe>
          </div>
        </form>
      </PopoverContent>
    </Popover>
  )
}

import { Maximize2Icon, Minimize2Icon } from 'lucide-react'
import { useEffect, useState } from 'react'
import TooltipButton from './tooltip-button'

const zoomInClassName =
  'bg-background fixed inset-0 z-50 p-6 [&_.tiptap]:max-h-[unset] [&_.tiptap]:min-h-[unset] [&_.tiptap]:h-full [&_.editor-content]:grow [&>div]:h-full [&>div]:flex [&>div]:flex-col [&_.editor-content]:overflow-auto'

export default function ZoomButton({ id }: { id: string }) {
  const [zoomed, setZoomed] = useState(false)

  function toggleZoom() {
    const newZoomed = !zoomed
    const editorElement = document.querySelector(`#editor-${id}`)
    editorElement?.classList[newZoomed ? 'add' : 'remove'](...zoomInClassName.split(' '))
    setZoomed(newZoomed)
  }

  // Todo: Move to useKeyPress hook from @uidotdev/usehooks when available (currently this hook is experimental)
  // Info: https://usehooks.com/usekeypress
  useEffect(() => {
    const keydownHandler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        const editorElement = document.querySelector(`#editor-${id}`)
        editorElement?.classList.remove(...zoomInClassName.split(' '))
        setZoomed(false)
      }
    }
    window.addEventListener('keydown', keydownHandler)
    return () => {
      window.removeEventListener('keydown', keydownHandler)
    }
  }, [id])

  return (
    <TooltipButton
      Icon={zoomed ? Minimize2Icon : Maximize2Icon}
      label={zoomed ? 'Zoom out' : 'Zoom in'}
      onClick={toggleZoom}
    />
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

// Utils
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export interface FileAttributes {
  mime: string
  name: string
  size: number
  url: string
}

declare module '@tiptap/core' {
  interface Commands<ReturnType> {
    file: {
      insertFile: (options: FileAttributes) => ReturnType
    }
  }
}
